cd /tmp && python3 - <<'EOF'
import json,glob,re,collections
run='/workspace/runs/3d5eaf15599685284e38ed827189784dd727d28c'
mem=json.load(open(f'{run}/LawBench/memory.json'))['examples']
tgt={e['target'] for e in mem}
parts=set()
for t in tgt:
    for p in t.split(';'): parts.add(p.strip())
def ents(s):
    s=re.sub(r'^\[罪名\]','',s or '').replace('<eoa>','')
    return [p.strip() for p in s.split(';') if p.strip()]
def split_msgs(j):
    draft=[]; tool=[]; other=[]
    for m in j.get('messages',[]):
        c=m['content']
        if isinstance(c,list):
            c=''.join(b if isinstance(b,str) else b.get('text','') for b in c)
        c=str(c)
        r=m.get('role')
        if r=='tool': tool.append(c)
        elif r=='assistant': draft.append(c)
        else: other.append(c)
    return '\n'.join(draft), '\n'.join(tool)
stats=collections.Counter(); rows=[]
for f in sorted(glob.glob(f'{run}/LawBench/conversations/*/sample-*.json')):
    j=json.load(open(f))
    if j.get('was_correct') or j.get('status')!='ok' or not j.get('prediction'): continue
    p=set(ents(j['prediction'])); t=set(ents(j['target']))
    miss=t-p
    if not miss: continue
    d, tl = split_msgs(j)
    for m in miss:
        inkey=(m in tgt) or (m in parts)
        stats['missing']+=1
        if inkey: stats['in_key']+=1
        if m in d: stats['in_own_answer_text']+=1
        if m in d and inkey: stats['own_text_and_in_key']+=1
        if m not in d and m in tl: stats['only_in_examples']+=1
        if m not in d and m not in tl: stats['nowhere']+=1
        rows.append((j['example_index'], m, inkey, m in d, m in tl))
print(stats)
print()
for r in rows: print(f'q{r[0]:02d} key={int(r[2])} own={int(r[3])} ex={int(r[4])}  {r[1]}')
EOF

