import json,glob,re,collections
run='/workspace/runs/3d5eaf15599685284e38ed827189784dd727d28c'
mem=json.load(open(f'{run}/LawBench/memory.json'))['examples']
tgt={e['target'] for e in mem}
parts=set()
for t in tgt:
    for p in t.split(';'): parts.add(p.strip())
def ents(s):
    s=re.sub(r'^\[罪名\]','',s or '').replace('<eoa>','')
    return [p.strip() for p in s.split(';') if p.strip()]
stats=collections.Counter(); rows=[]
for f in sorted(glob.glob(f'{run}/LawBench/conversations/*/sample-*.json')):
    j=json.load(open(f))
    if j.get('was_correct') or j.get('status')!='ok' or not j.get('prediction'): continue
    p=set(ents(j['prediction'])); t=set(ents(j['target']))
    miss=t-p
    if not miss: continue
    toolmsg=''
    for m in j['messages']:
        if m.get('role')=='tool':
            c=m['content']
            if isinstance(c,list): c=''.join(b if isinstance(b,str) else b.get('text','') for b in c)
            toolmsg=c
            break
    # split into example lines 'A: ...' and key lines
    example_answers=set()
    for line in toolmsg.split('\n'):
        s=line.strip()
        if s.startswith('A: '):
            for e2 in s[3:].split(';'):
                example_answers.add(e2.strip())
    for m in miss:
        inkey=(m in tgt) or (m in parts)
        stats['missing']+=1
        if inkey: stats['in_key']+=1
        # demonstrated: some delivered example has this entry as (part of) its answer
        demo = any(m==a or m in a or a in m for a in example_answers)
        if inkey and demo: stats['in_key_demonstrated']+=1
        if inkey and not demo: stats['in_key_not_demonstrated']+=1
        rows.append((j['example_index'], m, inkey, demo))
print(stats)
print()
for r in rows:
    if r[2]: print(f'q{r[0]:02d} demo={int(r[3])}  {r[1]}')
