    sc=[(_similarity(q,_ngrams(e.get('raw_question', e['input']))), i) for i,e in enumerate(examples)]
    sc.sort(key=lambda t:(-t[0],t[1])); return [examples[i] for _,i in sc]

def rank_pruned(examples, query):
    docs=[_ngrams(e.get('raw_question', e['input'])) for e in examples]
    df=collections.Counter()
    for d in docs: df.update(d.keys())
    q=collections.Counter({g:c for g,c in _ngrams(query).items() if g in df})
    sc=[(_similarity(q,d), i) for i,d in enumerate(docs)]
    sc.sort(key=lambda t:(-t[0],t[1])); return [examples[i] for _,i in sc]

def rank_coverage(examples, query):
    q=_ngrams(query)
    docs=[_ngrams(e.get('raw_question', e['input'])) for e in examples]
    sc=[(sum((q & d).values())/max(1,sum(d.values())), i) for i,d in enumerate(docs)]
    sc.sort(key=lambda t:(-t[0],t[1])); return [examples[i] for _,i in sc]

def rank_idf(examples, query):
    docs=[_ngrams(e.get('raw_question', e['input'])) for e in examples]
    df=collections.Counter()
    for d in docs: df.update(d.keys())
    n=len(docs)
    q=_ngrams(query)
    def w(g): return math.log((n+1)/(df.get(g,0)+1))+1.0
    def vec(c): return {g: c[g]*w(g) for g in c}
    qv=vec(q)
    sc=[]
    for i,d in enumerate(docs):
        dv=vec(d)
        num=sum(qv[g]*dv[g] for g in qv.keys() & dv.keys())
        den=(sum(v*v for v in qv.values())*sum(v*v for v in dv.values()))**0.5
